    for char in s:
        if char.lower() in {'a', 'e', 'i', 'o', 'u'}:
            vowels.append(char)
    result = []
    vowel_ptr = len(vowels) - 1
    for char in s:
        if char.lower() in {'a', 'e', 'i', 'o', 'u'}:
